package com.jinloes.practice;
import static org.assertj.core.api.Assertions.assertThat;
public final class ExampleRunner { private static final String USAGE="Input: semicolon-separated operations hit <time> and count <time>, for example: hit 1; hit 2; hit 300; count 300"; private ExampleRunner(){} public static void main(String[] args){ if (args.length > 0) { runInput(String.join(" ",args).trim()); return;} Solution a=new Solution(); a.hit(1); a.hit(2); a.hit(300); assertThat(a.hitsInLastWindow(300)).as("Example 1").isEqualTo(3); Solution b=new Solution(); b.hit(1); b.hit(301); assertThat(b.hitsInLastWindow(301)).as("Example 2").isEqualTo(1); Solution c=new Solution(); c.hit(5); c.hit(5); c.hit(304); assertThat(c.hitsInLastWindow(304)).as("Example 3").isEqualTo(3); System.out.println("Examples passed: 3"); } private static void runInput(String input){ try{ Solution c=new Solution(); Integer last=null; for(String op:input.split(";")){ String[] p=op.trim().split("\s+"); if(p.length!=2) throw new IllegalArgumentException(); int t=Integer.parseInt(p[1]); if(p[0].equals("hit")) c.hit(t); else if(p[0].equals("count")) last=c.hitsInLastWindow(t); else throw new IllegalArgumentException(); } if(last==null) throw new IllegalArgumentException(); System.out.println("hitsInLastWindow = "+last); }catch(RuntimeException e){ System.out.println("Could not read operations. "+USAGE); } } }
